import { useEffect, useState } from "react";
import CryptoJS from "crypto-js";

type SetValue<T> = T | ((val: T) => T);

interface UseLocalStorageOptions {
  encrypted?: boolean;
}

const SECRET_KEY = `${import.meta.env.VITE_SECRET_KEY}`;

// Save encrypted data
export const setData = (storageKey: string, value: any) => {
  try {
    const jsonValue = JSON.stringify(value);
    const encrypted = CryptoJS.AES.encrypt(jsonValue, SECRET_KEY).toString();
    localStorage.setItem(storageKey, encrypted);
    window.dispatchEvent(new Event("storage"));
  } catch (e) {
    console.error("Gagal menyimpan di localStorage", e);
    return null;
  }
};

// Retrieve and decrypt data with self-healing corrupted data cleanup
export const getData = (storageKey: string) => {
  try {
    const encrypted = localStorage.getItem(storageKey);
    if (!encrypted) return null;
    const bytes = CryptoJS.AES.decrypt(encrypted, SECRET_KEY);
    const decrypted = bytes.toString(CryptoJS.enc.Utf8);
    if (!decrypted) {
      console.error(`Failed to decrypt data for key: ${storageKey} - removing corrupted data`);
      localStorage.removeItem(storageKey);
      return null;
    }
    return JSON.parse(decrypted);
  } catch (e) {
    console.error(`Error retrieving data for key: ${storageKey}`, e);
    localStorage.removeItem(storageKey);
    return null;
  }
};

function useLocalStorage<T>(
  key: string,
  initialValue: T,
  options: UseLocalStorageOptions = {}
): [T, (value: SetValue<T>) => void] {
  const { encrypted = false } = options;

  const [storedValue, setStoredValue] = useState<T>(() => {
    if (typeof window !== "undefined") {
      try {
        if (encrypted) {
          const item = getData(key);
          if (item !== null) return item;
          if (initialValue) setData(key, initialValue);
          return initialValue;
        } else {
          const item = localStorage.getItem(key);
          if (item !== null) return JSON.parse(item);
          if (initialValue) localStorage.setItem(key, JSON.stringify(initialValue));
          return initialValue;
        }
      } catch (error) {
        return initialValue;
      }
    }
    return initialValue;
  });

  useEffect(() => {
    const handleStorageChange = () => {
      if (typeof window !== "undefined") {
        try {
          if (encrypted) {
            const newValue = getData(key);
            if (newValue !== null) setStoredValue(newValue);
          } else {
            const newValue = localStorage.getItem(key);
            if (newValue !== null) setStoredValue(JSON.parse(newValue));
          }
        } catch (error) {
          console.error(`Error syncing localStorage:`, error);
        }
      }
    };

    window.addEventListener("storage", handleStorageChange);
    return () => window.removeEventListener("storage", handleStorageChange);
  }, [key, encrypted]);

  const setValue = (value: SetValue<T>) => {
    const newValue = value instanceof Function ? value(storedValue) : value;
    setStoredValue(newValue);
    if (typeof window !== "undefined") {
      if (encrypted) {
        setData(key, newValue);
      } else {
        localStorage.setItem(key, JSON.stringify(newValue));
        window.dispatchEvent(new Event("storage"));
      }
    }
  };

  return [storedValue, setValue];
}

// Flatten and sort payload parameters for deterministic hashing
function flattenObject(obj: any, prefix: string = ""): any {
  let flattened: any = {};
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];
      const prefixedKey = prefix === "" ? key : `${prefix}.${key}`;
      if (typeof value === "object" && value !== null && !Array.isArray(value)) {
        const nested = flattenObject(value, prefixedKey);
        flattened = { ...flattened, ...nested };
      } else if (Array.isArray(value)) {
        flattened[prefixedKey] = "";
      } else {
        flattened[prefixedKey] = value;
      }
    }
  }
  return flattened;
}

export const makeSignature = (
  email: number,
  timestamp: number,
  data: any,
  isFormData?: boolean
) => {
  const formDataObject: any = { email, timestamp };
  if (isFormData) {
    for (const pair of data.entries()) {
      formDataObject[pair[0]] = pair[1];
    }
  }
  const newPayload = isFormData ? formDataObject : { email, ...data, timestamp };
  const finalPayload = formatObject(newPayload);
  return CryptoJS.SHA1(finalPayload);
};

