import { toast } from "@/components/ui/toast";
import { AxiosError } from "axios";

export interface ApiError {
  code: number;
  message: string;
  errors?: Record<string, string>;
  result: null;
}

export const formatErrorMessage = (error: unknown): string[] => {
  const axiosError = error as AxiosError<ApiError>;
  const apiError = axiosError.response?.data;

  if (!apiError) {
    return [axiosError.message || "An error occurred"];
  }

  // If we have field-specific validation errors
  if (apiError.errors && Object.keys(apiError.errors).length > 0) {
    return Object.values(apiError.errors);
  }

  // If we have a general error message
  if (apiError.message) {
    const formattedMessage = apiError.message.charAt(0).toUpperCase() + apiError.message.slice(1);
    return [formattedMessage];
  }

  return ["An error occurred"];
};

export function unwrapResult<T>(response: {
  code?: number;
  message?: string;
  result?: T | null;
}): T {
  if (response.code && response.code !== 200) {
    throw new Error(response.message || 'Request gagal');
  }

  if (!response.result) {
    throw new Error(response.message || 'Data tidak ditemukan');
  }

  return response.result;
}

export const showErrorToast = (error: AxiosError<ApiError>) => {
  const errors = formatErrorMessage(error);
  const errorList = errors.map(err => `• ${err}`).join('\n');

  toast.add({
    title: "Error",
    type: "error",
    description: errorList,
  });
};

// Image thumbnail fetcher with Blob and Object URL cleanup
export const ThumbnailImage: React.FC<ThumbnailImageProps> = ({
  photoId,
  alt = '',
  className = '',
}) => {
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<boolean>(false);

  useEffect(() => {
    let isMounted = true;
    let createdUrl: string | null = null;

    const loadThumbnail = async () => {
      setLoading(true);
      setError(false);
      try {
        const endpoint = PostMediaService.getThumbnailUrl(photoId);
        const response = await axios.get(endpoint, { responseType: 'blob' });

        if (isMounted) {
          const rawContentType = response.headers['content-type'];
          const contentType = typeof rawContentType === 'string' ? rawContentType : 'image/jpeg';
          const blob = new Blob([response.data], { type: contentType });
          createdUrl = URL.createObjectURL(blob);
          setImageUrl(createdUrl);
          setLoading(false);
        }
      } catch {
        if (isMounted) {
          const baseUrl = import.meta.env.VITE_API_URL || '';
          setImageUrl(`${baseUrl}/post-media/${photoId}/thumbnail`);
          setError(true);
          setLoading(false);
        }
      }
    };

    if (photoId) {
      loadThumbnail();
    } else {
      setLoading(false);
      setError(true);
    }

    return () => {
      isMounted = false;
      if (createdUrl) {
        URL.revokeObjectURL(createdUrl);
      }
    };
  }, [photoId]);

  if (loading) return <div className="absolute inset-0 animate-pulse bg-muted/60" />;
  return <img src={imageUrl || ''} alt={alt} className={className} onError={() => setError(true)} />;
};

// Authenticated file download with progress tracking
downloadPhoto: async (
  photoId: string,
  filename?: string,
  onProgress?: (progress: number) => void
): Promise<void> => {
  const response = await axios.get(`/post-media/${photoId}/download`, {
    responseType: "blob",
    onDownloadProgress: (progressEvent) => {
      if (progressEvent.total) {
        const percentCompleted = Math.round(
          (progressEvent.loaded * 100) / progressEvent.total
        );
        onProgress?.(percentCompleted);
      }
    },
  });
  const rawContentType = response.headers["content-type"];
  const contentType = typeof rawContentType === "string" ? rawContentType : "image/jpeg";
  const blob = new Blob([response.data], { type: contentType });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename || `photo-${photoId}.jpg`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

// PrivateRoute: Guarantees authenticated access with preserved navigation state
const PrivateRoute: React.FC<IPrivateRoute> = ({ children }: IPrivateRoute) => {
  const [token] = useLocalStorage<string | null>(LOCALSTORAGE_KEY.TOKEN, null, { encrypted: true });
  const location = useLocation();

  if (!token) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  return <>{children}</>;
};

// PublicRoute: Prevents logged-in users from visiting auth pages
const PublicRoute: React.FC<IPublicRoute> = ({ children }: IPublicRoute) => {
  const [token] = useLocalStorage<string | null>(LOCALSTORAGE_KEY.TOKEN, null, { encrypted: true });
  const location = useLocation();

  if (token) {
    return <Navigate to="/" replace state={{ from: location }} />;
  }

  return <>{children}</>;
};

